def transform(grid):
    """Fill background cells strictly between the first and last marker in each row or column."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    marker = next((v for row in grid for v in row if v not in (grid[0][0],)), None)
    # The marker is the non-background color; ARC inputs here contain one background and one marker.
    if marker is None:
        return out
    bg = grid[0][0]
    for r, row in enumerate(grid):
        xs = [c for c, v in enumerate(row) if v == marker]
        if len(xs) >= 2:
            for c in range(xs[0] + 1, xs[-1]):
                if out[r][c] == bg:
                    out[r][c] = 3
    for c in range(w):
        ys = [r for r in range(h) if grid[r][c] == marker]
        if len(ys) >= 2:
            for r in range(ys[0] + 1, ys[-1]):
                if out[r][c] == bg:
                    out[r][c] = 3
    return out

